// Highlights the nav link of the section currently on screen.
(function () {
  var links = document.querySelectorAll('nav a[href^="#"]');
  var sections = [];
  links.forEach(function (a) {
    var s = document.querySelector(a.getAttribute('href'));
    if (s) sections.push({ link: a, el: s });
  });
  if (!('IntersectionObserver' in window)) return;
  var observer = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (!entry.isIntersecting) return;
      links.forEach(function (a) { a.classList.remove('active'); });
      sections.forEach(function (s) {
        if (s.el === entry.target) s.link.classList.add('active');
      });
    });
  }, { rootMargin: '-30% 0px -60% 0px' });
  sections.forEach(function (s) { observer.observe(s.el); });
})();

// Certificate images (embedded so no image folder is needed) and click-to-enlarge.
var CERTS = {"isjem": "data:image/jpeg;base64,", "skilldzire": "data:image/jpeg;base64,", "slashmark": "data:image/jpeg;base64,", "nptel": "data:image/jpeg;base64,", "ia": "data:image/jpeg;base64,", "typing": "data:image/jpeg;base64,"};
(function () {
  var imgs = document.querySelectorAll('img[data-cert]');
  imgs.forEach(function (img) {
    var src = CERTS[img.getAttribute('data-cert')];
    if (src) img.src = src;
    img.addEventListener('click', function () {
      var box = document.createElement('div');
      box.className = 'lb';
      var big = document.createElement('img');
      big.src = img.src; big.alt = img.alt;
      box.appendChild(big);
      function close() { box.remove(); document.removeEventListener('keydown', onKey); }
      function onKey(e) { if (e.key === 'Escape') close(); }
      box.addEventListener('click', close);
      document.addEventListener('keydown', onKey);
      document.body.appendChild(box);
    });
  });
})();
